def compute(payload):
    """为每个 get 的原始位置生成 [若启动时的完成时刻,value,error]；只有命中未复用时才实际启动。"""
    events = payload["events"]
    result = {}
    for i, event in enumerate(events):
        if event.get("op") != "get":
            continue
        finished_at = event["time"] + event["delay"]
        value = event["value"]
        error = event.get("error", None)
        result[str(i)] = [finished_at, value, error]
    return result

import json
import sys
import unittest
from pathlib import Path

ROOT = Path(__file__).resolve().parents[2]
sys.path.insert(0, str(ROOT))

from components.load_proposals.work import compute


class TestLoadProposals(unittest.TestCase):
    def test_public_fixture(self):
        payload = json.loads((ROOT / "components/load_proposals/input.json").read_text())
        result = compute(payload)
        self.assertEqual(result, {"0": [3, 1, None], "2": [7, 9, None]})

    def test_error_defaults_to_null(self):
        payload = {
            "events": [
                {"op": "get", "time": 0, "id": "a", "key": "k", "delay": 2, "value": 5}
            ]
        }
        result = compute(payload)
        self.assertEqual(result, {"0": [2, 5, None]})

    def test_error_preserved(self):
        payload = {
            "events": [
                {"op": "get", "time": 1, "id": "a", "key": "k", "delay": 0, "value": None, "error": "boom"}
            ]
        }
        result = compute(payload)
        self.assertEqual(result, {"0": [1, None, "boom"]})

    def test_non_get_events_skipped(self):
        payload = {
            "events": [
                {"op": "advance", "time": 3},
                {"op": "get", "time": 4, "id": "b", "key": "k", "delay": 1, "value": 7, "error": None},
                {"op": "cancel", "time": 5, "id": "b"},
            ]
        }
        result = compute(payload)
        self.assertEqual(result, {"1": [5, 7, None]})


if __name__ == "__main__":
