    loads = []
    cache = {}  # key -> {"value":..., "error":..., "expires":...}
    in_flight = {}  # key -> {"started_at":..., "finished_at":..., "value":..., "error":..., "waiters":[...]}
    next_cleanup = 16 * ttl

