        key = min(in_flight, key=lambda k: in_flight[k]["started_at"])
        finish_load(key)

    # Sort cache by key.
    cache_list = [
        {
            "key": key,
            "value": cache[key]["value"],
            "error": cache[key]["error"],
            "expires": cache[key]["expires"],
        }
        for key in sorted(cache)
    ]

    return {
        "results": results,
        "loads": loads,
        "cache": cache_list,
        "next_cleanup": next_cleanup,
